    boardState.forEach(col => {
      col.cards = col.cards.filter(c => c.id !== updatedCard.id);
    });

    // Add to target column
    const targetCol = boardState.find(col => col.id === colId);
    if (targetCol) {
      targetCol.cards.push(updatedCard);
      renderBoard();
    }
