          targetCol.cards[idx] = canonicalCard;
        } else {
          targetCol.cards.push(canonicalCard);
        }

        // Re-render to ensure canonical order
        renderBoard();
      } catch (e) {
        alert('Error moving card');
        fetchBoard();
      }
    });
