        // Replace temp card with real card
        const cardIdx = col.cards.findIndex(c => c.id === tempId);
        if (cardIdx !== -1) col.cards[cardIdx] = newCard;
        renderBoard();
      } catch (e) {
        alert('Error adding card');
        col.cards = col.cards.filter(c => c.id !== tempId);
        renderBoard();
      }
      input.value = '';
    };

